INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Gizlilik Politikası', 'gizlilik-politikasi', 'Kişisel verilerinizin nasıl toplandığını, kullanıldığını ve korunduğunu açıklayan gizlilik politikası.',
$tt${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu gizlilik politikası, {domain} üzerinden sunulan hizmetlerde kişisel verilerinizin nasıl toplandığını, kullanıldığını, paylaşıldığını ve korunduğunu sade bir dille açıklar. Hukuki ayrıntılar için "}, {"type": "text", "text": "KVKK Aydınlatma Metni", "marks": [{"type": "link", "attrs": {"href": "/kvkk"}}]}, {"type": "text", "text": "'ne, Avrupa Birliği'nden ziyaret ediyorsanız "}, {"type": "text", "text": "GDPR Bilgilendirme Metni", "marks": [{"type": "link", "attrs": {"href": "/gdpr"}}]}, {"type": "text", "text": "'ne, çerezler için "}, {"type": "text", "text": "Çerez Politikası", "marks": [{"type": "link", "attrs": {"href": "/cerez-politikasi"}}]}, {"type": "text", "text": "'na bakabilirsiniz."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Son güncelleme: 14 Kasım 2026."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Kapsam"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu politika; siteyi ziyaret eden herkesi, üyeleri, bülten abonelerini, yorum yapanları ve bizimle iletişime geçenleri kapsar. Sitemizden bağlantı verilen üçüncü taraf siteler kendi gizlilik politikalarına tabidir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Topladığımız Veriler"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sizin verdikleriniz: ad, e-posta adresi, yorum ve mesaj içerikleri, üyelik ve abonelik bilgileri."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Otomatik toplananlar: IP adresi, tarayıcı ve cihaz bilgisi, ziyaret zamanı, görüntülenen sayfalar, dil ve tema tercihi."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Konum: IP adresinizden türetilen ülke bilgisi; ayrıca tarayıcınızın konum iznini verirseniz yaklaşık konumunuz."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Çerezler: sitenin çalışması için zorunlu olanlar ile onayınıza bağlı analitik ve reklam çerezleri."}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Verileri Nasıl Kullanıyoruz"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Siteyi ve içerikleri sunmak, hesabınızı ve aboneliklerinizi yönetmek,"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Güvenliği sağlamak, kötüye kullanımı önlemek,"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hangi içeriklerin ilgi gördüğünü ve ziyaretlerin hangi bölgelerden geldiğini anlamak,"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İzin verdiyseniz bülten ve bildirim göndermek,"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Onay verdiyseniz reklam göstermek ve reklam performansını ölçmek,"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yasal yükümlülüklerimizi yerine getirmek."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Kişisel verilerinizi satmayız."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Konum Verisi"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitemiz iki farklı düzeyde konum bilgisi işler:"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ülke: her ziyarette, IP adresinize karşılık gelen ülke kodu kaydedilir. Bunun için sizden izin istenmez; ziyaret istatistiği amacıyla kullanılır."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Yaklaşık konum: sayfa açıldığında tarayıcınız konum izni isteyebilir. İzin verirseniz enlem ve boylam bilginiz yaklaşık 11 metre hassasiyete yuvarlanarak kaydedilir; adresiniz kaydedilmez. İzin vermezseniz yalnızca ülke bilgisi işlenir ve siteyi aynı şekilde kullanmaya devam edersiniz."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Konum kaydı adınız, e-posta adresiniz veya üyelik hesabınızla eşleştirilmez; tarayıcınıza atanan rastgele bir kimlikle tutulur. IP adresi yönetim panelinde maskelenerek gösterilir. Konum verisi reklam veya pazarlama amacıyla kimseyle paylaşılmaz; yöneticinin bir konumu harita üzerinde görüntülemesi hâlinde ilgili koordinat harita hizmeti sağlayıcısına (Google Haritalar) iletilir. Kayıtlar son ziyaretinizden 12 ay sonra silinir. İzni tarayıcınızın site ayarlarından dilediğiniz zaman geri alabilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Trafik Güvenliği"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bot ve sahte trafiği gerçek ziyaretlerden ayırmak için bağlantınızı otomatik olarak değerlendiririz. Bu amaçla IP adresinizin ait olduğu ağ ve sağlayıcı, VPN, proxy veya veri merkezi kullanımına ilişkin işaretler ile tarayıcınızın bildirdiği bazı teknik bilgiler (ek IP adresleri, otomasyon işaretleri, saat dilimi, dil) işlenir ve bir risk puanı hesaplanır. Şüpheli görülen bağlantılar okunma sayımına katılmaz, bu bağlantılara reklam gösterilmeyebilir veya erişim kısıtlanabilir. Kayıtlar son ziyaretinizden 12 ay sonra silinir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Çerezler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Zorunlu çerezler sitenin çalışması için gereklidir. Analitik ve reklam çerezleri yalnızca onay verirseniz kullanılır; tercihinizi sayfa altındaki \"Çerez tercihleri\" bağlantısından dilediğiniz zaman değiştirebilirsiniz. Kullanılan çerezlerin tam listesi "}, {"type": "text", "text": "Çerez Politikası", "marks": [{"type": "link", "attrs": {"href": "/cerez-politikasi"}}]}, {"type": "text", "text": "'nda yer alır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Verilerin Paylaşılması"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Verileriniz yalnızca hizmetin gerektirdiği ölçüde şu taraflarla paylaşılır: içerik dağıtım ve güvenlik hizmeti (Cloudflare), barındırma, e-posta gönderimi ve ödeme hizmeti sağlayıcıları; onay vermeniz hâlinde ölçüm hizmeti (Google Analytics, Google Tag Manager) ve reklam ağları (Coinzilla, Cointraffic); hukuken zorunlu olduğunda yetkili kamu kurumları. Bu sağlayıcıların bir kısmı yurt dışında yerleşiktir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Güvenlik"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Site yalnızca şifreli bağlantı (HTTPS) üzerinden sunulur. Kişisel verilere erişim yetkili kişilerle sınırlıdır; parolalar geri döndürülemez biçimde saklanır. İnternet üzerinden yapılan hiçbir aktarımın tümüyle güvenli olduğu garanti edilemez; bir veri ihlali hâlinde mevzuatın öngördüğü bildirimler yapılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. Saklama"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Verilerinizi, toplandıkları amaç için gereken süre ve yasal saklama süreleri boyunca tutarız. Ayrıntılı süreler "}, {"type": "text", "text": "KVKK Aydınlatma Metni", "marks": [{"type": "link", "attrs": {"href": "/kvkk"}}]}, {"type": "text", "text": "'nin 6. bölümündedir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "10. Çocuklar"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sitemiz 18 yaşından küçüklere yönelik değildir ve bilerek 18 yaşından küçüklerden kişisel veri toplamayız."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "11. Haklarınız"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Verilerinize erişme, düzeltilmesini veya silinmesini isteme, işlemeye itiraz etme ve rızanızı geri alma haklarına sahipsiniz. Üyeler hesaplarını hesap ayarlarından kalıcı olarak silebilir. Taleplerinizi "}, {"type": "text", "text": "İlgili Kişi Başvuru Formu", "marks": [{"type": "link", "attrs": {"href": "/kvkk-basvuru"}}]}, {"type": "text", "text": " veya {eposta_kvkk} üzerinden iletebilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "12. Değişiklikler ve İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu politika güncellenebilir; güncel metin bu sayfada yayımlanır. Sorularınız için: {eposta_kvkk}."}]}]}$tt$::jsonb, 'yayinda', false, true, true)
ON CONFLICT (slug) DO UPDATE SET
    title = EXCLUDED.title,
    spot = EXCLUDED.spot,
    detail = EXCLUDED.detail,
    kind = EXCLUDED.kind,
    status = 'yayinda',
    in_footer = true,
    updated_at = now();

INSERT INTO pages (kind, title, slug, spot, detail, status, in_menu, in_footer, is_locked)
VALUES ('kurumsal', 'Çerez Politikası ve Aydınlatma Metni', 'cerez-politikasi', 'Sitemizde kullanılan çerezler, amaçları, süreleri ve tercihlerinizi yönetme yolları.',
$tt${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu metin, {domain} üzerinde kullanılan çerezler ve benzeri teknolojiler (yerel depolama gibi) hakkında sizi bilgilendirmek amacıyla hazırlanmıştır. Çerezler, ziyaret ettiğiniz sitelerin tarayıcınıza kaydettiği küçük metin dosyalarıdır."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Son güncelleme: 14 Kasım 2026."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Çerezleri Nasıl Kullanıyoruz"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Çerezleri üç grupta kullanıyoruz. Zorunlu çerezler ile sitenin kendi ölçüm çerezleri sitenin işleyişinin parçasıdır. Analitik ve reklam çerezleri ise yalnızca siz onay verirseniz yerleştirilir; onay vermediğinizde ilgili üçüncü taraf betikleri hiç yüklenmez ve site aynı şekilde çalışmaya devam eder."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. Zorunlu Çerezler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Oturum, güvenlik ve tercihlerinizin hatırlanması için gereklidir. Bu çerezler için onay istenmez."}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Çerez"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Amaç"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Süre"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_session"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Üye ve yönetim oturumunun sürdürülmesi"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 gün"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_uye"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ücretli üyeliğin tanınması"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 gün"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_gstate, tb_gredir"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Google ile giriş sırasında güvenlik doğrulaması ve yönlendirme"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Giriş işlemi süresince"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_flash"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tek seferlik bilgi mesajının gösterilmesi"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bir sonraki sayfaya kadar"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_riza"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Çerez tercihinizin saklanması"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "180 gün"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_konum"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tarayıcı konum izni durumunuzun (verildi veya reddedildi) hatırlanması"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 gün"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tema (yerel depolama)"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Açık veya koyu tema tercihiniz"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Siz silene kadar"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "__cf_bm, cf_clearance (Cloudflare)"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bot ve saldırı trafiğinin ayırt edilmesi, güvenlik doğrulaması"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 dakika ile 1 yıl arası"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "3. Sitenin Kendi Ölçüm Çerezleri"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu çerezler yalnızca sitemiz tarafından yerleştirilir ve okunur; üçüncü taraflarla paylaşılmaz. Ziyaret istatistiği tutmak ve aynı tarayıcıdan tekrarlanan işlemleri ayırt etmek için kullanılır."}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Çerez"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Amaç"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Süre"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_vid"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tarayıcıya atanan rastgele ziyaretçi kimliği; ziyaret ve konum istatistiğinde aynı tarayıcının tek kez sayılması, trafik güvenliği denetimi"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "365 gün"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_geo"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ülke bilgisinin en fazla saatte bir kaydedilmesi için zaman bilgisi"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "30 gün"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_visitor"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İçerik tepkilerinin (beğeni ve benzeri) aynı tarayıcıdan tekrarlanmasının önlenmesi"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "365 gün"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "tb_ab"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tasarım denemelerinde size aynı görünümün gösterilmesi"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "90 gün"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "4. Analitik Çerezler (Onayınıza Bağlı)"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Ziyaret sayısı, görüntülenen sayfalar ve trafik kaynakları gibi bilgileri ölçmek için kullanılır."}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sağlayıcı"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Çerezler"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Amaç"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Süre"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Google Analytics, Google Tag Manager"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "_ga, _ga_ ile başlayan çerezler"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Ziyaret ve sayfa görüntüleme ölçümü"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "2 yıla kadar"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "5. Reklam Çerezleri (Onayınıza Bağlı)"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Reklamların gösterilmesi, gösterim sıklığının sınırlanması ve reklam performansının ölçülmesi için reklam ağları tarafından yerleştirilir."}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sağlayıcı"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Amaç"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Süre"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Coinzilla"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklam gösterimi ve ölçümü"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sağlayıcının belirlediği süre"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cointraffic"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Reklam gösterimi ve ölçümü"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sağlayıcının belirlediği süre"}]}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Bu çerezler ilgili sağlayıcıların kendi gizlilik politikalarına tabidir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "6. Gömülü İçerikler"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Sayfalarımızda yer alan YouTube videolarını oynatmanız hâlinde YouTube (Google) kendi çerezlerini yerleştirebilir. Google hesabınızla giriş yapmayı seçmeniz hâlinde Google'ın giriş çerezleri kullanılır."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "7. Tercihlerinizi Yönetme"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "İlk ziyaretinizde açılan çerez kartından \"Yalnızca zorunlu\", \"Tümünü kabul et\" veya \"Tercihleri yönet\" seçeneklerinden birini seçebilirsiniz."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tercihinizi dilediğiniz zaman sayfa altındaki \"Çerez tercihleri\" bağlantısından değiştirebilir, onayınızı geri alabilirsiniz. Onayınızı geri aldığınızda analitik çerezler tarayıcınızdan silinir ve ilgili betikler yüklenmez."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tarayıcınızın ayarlarından çerezleri silebilir veya engelleyebilirsiniz. Zorunlu çerezleri engellemeniz hâlinde oturum açma gibi bazı işlevler çalışmayabilir."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Tercihiniz 180 gün boyunca saklanır; bu sürenin sonunda veya çerez politikamızda esaslı bir değişiklik olduğunda tercihiniz yeniden sorulur."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "8. Yurt Dışına Aktarım"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Analitik ve reklam hizmeti sağlayıcıları yurt dışında yerleşiktir. Bu çerezlere onay vermeniz, ilgili verilerin bu sağlayıcılara aktarılmasına da onay verdiğiniz anlamına gelir. Ayrıntılar "}, {"type": "text", "text": "KVKK Aydınlatma Metni", "marks": [{"type": "link", "attrs": {"href": "/kvkk"}}]}, {"type": "text", "text": "'nin 5. bölümündedir."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "9. İletişim"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Çerezlere ilişkin sorularınızı {eposta_kvkk} adresine iletebilirsiniz. Kişisel verilerinize ilişkin haklarınız için "}, {"type": "text", "text": "KVKK Aydınlatma Metni", "marks": [{"type": "link", "attrs": {"href": "/kvkk"}}]}, {"type": "text", "text": "'ne bakabilirsiniz."}]}]}$tt$::jsonb, 'yayinda', false, true, true)
