VALUES ('kurumsal', 'GDPR Bilgilendirme Metni', 'gdpr', 'AB, AEA ve Birleşik Krallık''tan ziyaret edenler için GDPR kapsamında bilgilendirme (Privacy Notice for EU/EEA/UK visitors).',
$tt${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Bu metin, Avrupa Birliği, Avrupa Ekonomik Alanı ve Birleşik Krallık'tan {domain} sitesini ziyaret eden kişileri, (AB) 2016/679 sayılı Genel Veri Koruma Tüzüğü (\"GDPR\") ve Birleşik Krallık GDPR'ı kapsamında, bu düzenlemelerin uygulanabildiği ölçüde bilgilendirmek için hazırlanmıştır. Metin, "}, {"type": "text", "text": "KVKK Aydınlatma Metni", "marks": [{"type": "link", "attrs": {"href": "/kvkk"}}]}, {"type": "text", "text": " ve "}, {"type": "text", "text": "Çerez Politikası", "marks": [{"type": "link", "attrs": {"href": "/cerez-politikasi"}}]}, {"type": "text", "text": " ile birlikte okunmalıdır. İngilizce metin aşağıdadır."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Son güncelleme: 14 Kasım 2026."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "1. Veri Sorumlusu"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Veri sorumlusu, {domain} sitesinin yayın sahibidir; unvan ve adres bilgileri "}, {"type": "text", "text": "Künye", "marks": [{"type": "link", "attrs": {"href": "/kunye"}}]}, {"type": "text", "text": " sayfasındadır. Veri koruma taleplerinizi {eposta_kvkk} adresine iletebilirsiniz."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "2. İşlenen Veriler, Amaçlar ve Hukuki Dayanaklar"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Amaç"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Veriler"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hukuki dayanak (GDPR md. 6)"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sitenin sunulması ve güvenliği"}]}]}, {"type